begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.mi(t text) returns uuid language sql immutable as $$select md5('member-draft-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.mi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-draft@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','candidate','foreign','unconfirmed']) t;
insert into public.organizations(id,name,slug,status) values(pg_temp.mi('org'),'Ministério fictício self','member-draft-test','active'),(pg_temp.mi('other'),'Outro ministério fictício','member-draft-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.mi('unit'),pg_temp.mi('org'),'Sede fictícia','sede','headquarters'),(pg_temp.mi('otherunit'),pg_temp.mi('other'),'Outra sede fictícia','sede','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) values(pg_temp.mi('ownermember'),pg_temp.mi('org'),pg_temp.mi('owner'),pg_temp.mi('unit'),'owner','active');
insert into public.people(id,organization_id,unit_id,full_name,email,status) values(pg_temp.mi('candidateperson'),pg_temp.mi('org'),pg_temp.mi('unit'),'Pessoa já cadastrada','candidate-draft@example.invalid','active');
create function pg_temp.submit(d jsonb) returns jsonb language sql as $$select public.member_self_service(pg_temp.mi('org'),'submit',pg_temp.mi('unit'),d)$$;
select ok(not has_function_privilege('anon','public.member_profile_draft(uuid,text,jsonb)','execute'),'visitante não grava rascunho');
select ok(not has_table_privilege('authenticated','private.member_profile_drafts','select'),'rascunho sem leitura direta');
set local role authenticated;
select pg_temp.actor('member');
select lives_ok($$select public.member_profile_draft(pg_temp.mi('org'),'save','{"full_name":"Rascunho fictício","cpf":"12345678909","street":""}')$$,'salva rascunho');
select is(public.member_profile_draft(pg_temp.mi('org'),'get')->'data'->>'cpf','12345678909','volta o que foi digitado');
select ok(not (public.member_profile_draft(pg_temp.mi('org'),'get')->'data') ? 'street','campos vazios não são guardados');
select throws_ok($$select public.member_profile_draft(pg_temp.mi('org'),'save','{"full_name":{"x":1}}')$$,'22023','invalid_member_draft','só texto no rascunho');
select pg_temp.actor('owner');
select is(public.member_profile_draft(pg_temp.mi('org'),'get')->'data','{}'::jsonb,'outra conta não vê o rascunho');
reset role;
select is((select count(*)::int from private.member_profile_requests where organization_id=pg_temp.mi('org')),0,'rascunho não aparece para a secretaria');
update private.member_profile_drafts set updated_at=now()-interval '31 days' where user_id=pg_temp.mi('member');
set local role authenticated;
select pg_temp.actor('member');
select is(public.member_profile_draft(pg_temp.mi('org'),'get')->'data','{}'::jsonb,'rascunho com mais de 30 dias é descartado');
select lives_ok($$select public.member_profile_draft(pg_temp.mi('org'),'save','{"full_name":"Pessoa fictícia app"}')$$,'salva de novo');
select lives_ok($$select pg_temp.submit('{"full_name":"Pessoa fictícia app","phone":"11999999999"}')$$,'envia para a igreja');
select is(public.member_profile_draft(pg_temp.mi('org'),'get')->'data','{}'::jsonb,'enviar apaga o rascunho');
reset role;
select is((select count(*)::int from private.member_profile_requests where organization_id=pg_temp.mi('org')),1,'pedido aparece para a secretaria só depois de enviar');
select * from finish();
rollback;
